            var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((double)(-1e30)); var uHi = Vec1((double)1e30);   // library's own "unbounded" sentinel (QP.solve's own INF convention)

            var K = new doubleMxN(1, 2, Allocator.Temp);
